# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ANA YURDUMUZ TÜRKİSTAN\'DA KURULAN İLK TÜRK DEVLETLERİ (SB.6.3.1)</text>\n  <rect x="20" y="48" width="210" height="192" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Asya Hun Devleti</text>\n  <text x="125" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">(MÖ 220 – MS 216 · Ötüken)</text>\n  <text x="32" y="120" font-size="11.5" fill="#1e3a8a">• Bilinen ilk Türk devletidir.</text>\n  <text x="32" y="142" font-size="11.5" fill="#1e3a8a">• Kurucusu: Teoman</text>\n  <text x="32" y="164" font-size="11.5" fill="#1e3a8a">• En parlak dönem: Metehan</text>\n  <text x="32" y="186" font-size="11.5" fill="#1e3a8a">• Türk boylarını ilk kez tek bayrak</text>\n  <text x="32" y="204" font-size="11.5" fill="#1e3a8a">altında topladı; Onlu sistemi kurdu.</text>\n  <text x="125" y="226" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Destan: Oğuz Kağan Destanı</text>\n\n  <rect x="245" y="48" width="210" height="192" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Kök Türk Devleti</text>\n  <text x="350" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#16a34a">(I: 552–630 / II: 682–744 · Ötüken)</text>\n  <text x="257" y="120" font-size="11.5" fill="#14532d">• «Türk» adını devlet adı olarak</text>\n  <text x="257" y="138" font-size="11.5" fill="#14532d">kullanan ilk devlettir (Bumin Kağan).</text>\n  <text x="257" y="160" font-size="11.5" fill="#14532d">• II. Kök Türk (Kutluk): İlteriş Kağan,</text>\n  <text x="257" y="178" font-size="11.5" fill="#14532d">Bilge Kağan, Kül Tigin, Tonyukuk.</text>\n  <text x="257" y="200" font-size="11.5" fill="#14532d">• 38 harfli Kök Türk alfabesi.</text>\n  <text x="350" y="226" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Eser: Orhun Yazıtları · Ergenekon</text>\n\n  <rect x="470" y="48" width="210" height="192" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">3. Uygur Devleti</text>\n  <text x="575" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#ca8a04">(744 – 840 · Ordubalık / Karabalgasun)</text>\n  <text x="482" y="120" font-size="11.5" fill="#713f12">• Kurucusu: Kutluk Bilge Kül Kağan</text>\n  <text x="482" y="142" font-size="11.5" fill="#713f12">• Yerleşik hayata geçen ilk Türk</text>\n  <text x="482" y="160" font-size="11.5" fill="#713f12">devletidir; şehir ve saray kurdular.</text>\n  <text x="482" y="182" font-size="11.5" fill="#713f12">• Tarım, sulama kanalı, kağıt, matbaa</text>\n  <text x="482" y="200" font-size="11.5" fill="#713f12">ve 18 harfli Uygur alfabesi.</text>\n  <text x="575" y="226" text-anchor="middle" font-size="11" font-weight="bold" fill="#a16207">Destan: Türeyiş ve Göç Destanları</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">YÖNETİM (KUT, KURULTAY), HUKUK (TÖRE) VE ORDU (ONLU SİSTEM)</text>\n  <rect x="20" y="48" width="210" height="192" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#be185d">Yönetim Anlayışı</text>\n  <text x="32" y="98" font-size="11.5" fill="#831843">• Kut Anlayışı: Yönetme yetkisinin</text>\n  <text x="32" y="116" font-size="11.5" fill="#831843">Gök Tanrı tarafından verilmesi.</text>\n  <text x="32" y="140" font-size="11.5" fill="#831843">• Kurultay (Toy): Siyasi ve askeri</text>\n  <text x="32" y="158" font-size="11.5" fill="#831843">kararların alındığı danışma meclisi.</text>\n  <text x="32" y="182" font-size="11.5" fill="#831843">• Hatun (Katun): Kurultaya katılır,</text>\n  <text x="32" y="200" font-size="11.5" fill="#831843">elçi kabul eder (kadına verilen değer).</text>\n  <text x="125" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#9d174d">İkili Teşkilat: Doğu (Merkez) - Batı</text>\n\n  <rect x="245" y="48" width="210" height="192" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#7e22ce">Hukuk Sistemi: Töre</text>\n  <text x="257" y="98" font-size="11.5" fill="#581c87">• Töre: Devlet ve toplum düzenini</text>\n  <text x="257" y="116" font-size="11.5" fill="#581c87">sağlayan sözlü hukuk kurallarıdır.</text>\n  <text x="257" y="140" font-size="11.5" fill="#581c87">• Kağan dahil herkes töreye uymak</text>\n  <text x="257" y="158" font-size="11.5" fill="#581843">zorundadır (hukukun üstünlüğü).</text>\n  <text x="257" y="182" font-size="11.5" fill="#581c87">• Törenin 4 değişmez ilkesi: Adalet</text>\n  <text x="257" y="200" font-size="11.5" fill="#581c87">(könilik), İyilik, Eşitlik, İnsanlık.</text>\n  <text x="350" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">«İl gider, töre kalır!»</text>\n\n  <rect x="470" y="48" width="210" height="192" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#0e7490">Ordu: Onlu Sistem</text>\n  <text x="482" y="98" font-size="11.5" fill="#155e75">• Ordu-millet anlayışı hâkimdir.</text>\n  <text x="482" y="120" font-size="11.5" fill="#155e75">• Onlu Sistem (MÖ 209): Metehan</text>\n  <text x="482" y="138" font-size="11.5" fill="#155e75">tarafından kuruldu (Onbaşı, Yüzbaşı,</text>\n  <text x="482" y="156" font-size="11.5" fill="#155e75">Binbaşı, Tümenbaşı = 10.000).</text>\n  <text x="482" y="180" font-size="11.5" fill="#155e75">• Savaş stratejisi: Turan (Hilal /</text>\n  <text x="482" y="198" font-size="11.5" fill="#155e75">Kurt Kapanı / Sahte Ricat) taktiği.</text>\n  <text x="575" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#0891b2">Modern Orduların Temeli</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İLK TÜRK DEVLETLERİNİN BİLİM, YAZI, EKONOMİ VE SANAT MİRASI</text>\n  <rect x="25" y="48" width="315" height="192" rx="8" fill="#fff7ed" stroke="#f97316" stroke-width="1.5"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#c2410c">Bilim, Yazı ve Edebiyat Katkıları</text>\n  <text x="40" y="98" font-size="11.5" fill="#9a3412">• 12 Hayvanlı Türk Takvimi: Astronomi ve matematik</text>\n  <text x="40" y="116" font-size="11.5" fill="#9a3412">bilgisinin kanıtıdır (Güneş yılı esaslı, 12 yıl).</text>\n  <text x="40" y="140" font-size="11.5" fill="#9a3412">• Milli Alfabeler: Kök Türk (38 harf) ve Uygur (18 harf).</text>\n  <text x="40" y="164" font-size="11.5" fill="#9a3412">• Orhun Yazıtları: Türk tarihinin ilk yazılı belgesi</text>\n  <text x="40" y="182" font-size="11.5" fill="#9a3412">(Bilge Kağan, Kül Tigin ve Vezir Tonyukuk adına).</text>\n  <text x="40" y="206" font-size="11.5" fill="#9a3412">• Uygurlarda kağıt üretimi ve hareketli harf matbaası.</text>\n  <text x="182" y="226" text-anchor="middle" font-size="11" font-weight="bold" fill="#ea580c">Sözlü Edebiyat: Sav, Sagu, Koşuk ve Destanlar</text>\n\n  <rect x="360" y="48" width="315" height="192" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Ekonomi, Madencilik ve Sanat Mirası</text>\n  <text x="375" y="98" font-size="11.5" fill="#14532d">• İpek Yolu ve Kürk Yolu ticareti; hayvancılık ve</text>\n  <text x="375" y="116" font-size="11.5" fill="#14532d">dokumacılık (Uygurlarda sulama kanalları ve tarım).</text>\n  <text x="375" y="140" font-size="11.5" fill="#14532d">• Pazırık Halısı: Dünyanın en eski düğümlü halısı</text>\n  <text x="375" y="158" font-size="11.5" fill="#14532d">(Pazırık Kurganı\'ndan çıkarılmıştır).</text>\n  <text x="375" y="182" font-size="11.5" fill="#14532d">• Altın Elbiseli Adam Zırhı (Esik Kurganı): Gelişmiş</text>\n  <text x="375" y="200" font-size="11.5" fill="#14532d">maden ve altın işçiliği · Hayvan üslubu ve Balballar.</text>\n  <text x="517" y="226" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Uygurlarda Mimari, Fresk (Duvar Resmi) ve Minyatür</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
